#!/usr/bin/env node
/**
 * check-text-integrity.mjs — catch the exact corruption mode that broke
 * scripts\fix-bash-terminal-import.mjs and the DSH Desktop path: a Windows path
 * written inside a double-quoted PowerShell string can turn `\f`, `\v`, `\a`,
 * `\r` into C0 control characters when the file is regenerated by a tool.
 *
 * Allowed: TAB, LF, CR. One deliberate exception: dsh-web-billing uses U+0000
 * inside a template literal as a composite-key separator.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = process.argv[2] || join(fileURLToPath(new URL('.', import.meta.url)), '..');
const EXTS = new Set(['.ps1', '.mjs', '.js', '.cjs', '.yml', '.yaml', '.json', '.md', '.txt', '.template', '.ts']);
const ALLOWED_NUL = new Set(['plugins/standalone/dsh-web-billing/lib/index.js']);
const problems = [];
let checked = 0;

function walk(dir) {
  for (const name of readdirSync(dir)) {
    if (name === '.git' || name === 'node_modules') continue;
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) { walk(full); continue; }
    if (!EXTS.has((name.match(/\.[^.]+$/) || [''])[0].toLowerCase())) continue;
    checked++;
    const rel = relative(REPO, full).replace(/\\/g, '/');
    const text = readFileSync(full, 'utf8');
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      if (code >= 32 || code === 9 || code === 10 || code === 13) continue;
      if (code === 0 && ALLOWED_NUL.has(rel)) continue;
      const line = text.slice(0, i).split(/\r?\n/).length;
      const context = text.slice(Math.max(0, i - 40), Math.min(text.length, i + 40)).replace(/\r/g, '<CR>').replace(/\n/g, '<LF>');
      problems.push(`${rel}:${line} U+${code.toString(16).toUpperCase().padStart(4, '0')} ${context}`);
      break;
    }
  }
}

walk(REPO);
if (problems.length) {
  for (const p of problems) console.error(`FAIL ${p}`);
  console.error(`\nchecked ${checked} text files, ${problems.length} corrupt file(s)`);
  process.exit(1);
}
console.log(`checked ${checked} text files, no stray C0 control characters`);
